import { useEffect, useMemo, useRef, useState } from 'react';
import { ArrowLeftRight, Barcode, Box, ClipboardCheck, LayoutDashboard, LogOut, MapPin, Menu, PackagePlus, QrCode, RotateCcw, ScanLine, Settings2, UserCircle, Warehouse } from 'lucide-react';
import QRCode from 'qrcode';

const apiUrl = import.meta.env.VITE_API_URL || `${window.location.protocol}//${window.location.hostname}:4000/api`;
const navigation = [['panel', 'Panel', LayoutDashboard], ['urunler', 'Ürünler', Box], ['giris', 'Stok girişi', PackagePlus], ['cikis', 'Çıkış / zimmet', ScanLine], ['transfer', 'Depo transferi', ArrowLeftRight], ['iade', 'İade kabulü', RotateCcw], ['sayim', 'Sayım', ClipboardCheck], ['etiket', 'Etiket merkezi', QrCode], ['konumlar', 'Depolar ve raflar', Warehouse], ['yonetim', 'Yönetim', Settings2]];
const flowLabels = { IN: 'Stok girişi', OUT: 'Çıkış / zimmet', TRANSFER: 'Depo transferi', TRANSFER_OUT: 'Depo transferi', RETURN: 'İade kabulü', COUNT: 'Sayım', COUNT_ADJUSTMENT: 'Sayım' };
const unitStatusLabels = { IN_STOCK: 'Depoda', RESERVED: 'Ayrıldı', ASSIGNED: 'Zimmetli', OUT_OF_STOCK: 'Depo dışı', RETURNED: 'İade edildi', SCRAPPED: 'Hurda' };
const movementTypeLabels = { ...flowLabels, TRANSFER_IN: 'Depo transferi', COUNT_ADJUSTMENT: 'Sayım düzeltmesi', ORDER: 'Sipariş' };
const formatDate = (value) => value ? new Date(value).toLocaleString('tr-TR') : '—';

async function request(path, options = {}) {
  const token = localStorage.getItem('barfas_auth_token');
  const headers = { 'Content-Type': 'application/json', ...(options.headers || {}) };
  if (token) headers.Authorization = `Bearer ${token}`;
  const response = await fetch(`${apiUrl}${path}`, { ...options, headers });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) { const error = new Error(body.message || 'İşlem tamamlanamadı.'); error.status = response.status; throw error; }
  return body;
}
function Metric({ label, value, alert }) { return <article className={`metric ${alert ? 'metric-alert' : ''}`}><span>{label}</span><strong>{value ?? '—'}</strong></article>; }
function Notice({ notice }) { return notice ? <div className={`notice ${notice.type}`}>{notice.text}</div> : null; }

function LoginPage({ onAuthenticated }) {
  const [mode, setMode] = useState('login');
  const [form, setForm] = useState({ username: '', password: '', fullName: '' });
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);

  async function submit(event) {
    event.preventDefault(); setError(''); setSaving(true);
    try {
      const result = await request(`/auth/${mode === 'login' ? 'login' : 'register'}`, { method: 'POST', body: JSON.stringify(form) });
      localStorage.setItem('barfas_auth_token', result.token);
      onAuthenticated(result.user);
    } catch (requestError) { setError(requestError.message); } finally { setSaving(false); }
  }

  return <div className="auth-shell"><section className="auth-card">
    <div className="auth-brand"><span className="auth-logo">B</span><div><strong>Barfas</strong><small>Depo Yönetimi</small></div></div>
    <p className="eyebrow">GÜVENLİ GİRİŞ</p><h1>{mode === 'login' ? 'Hesabınıza giriş yapın' : 'Yeni hesap oluşturun'}</h1>
    <p className="auth-intro">Stok hareketlerinin kimin tarafından yapıldığını takip etmek için kişisel hesabınızı kullanın.</p>
    {error && <div className="notice error">{error}</div>}
    <form className="auth-form" onSubmit={submit}>
      {mode === 'register' && <label>Ad soyad<input required minLength="2" value={form.fullName} onChange={(e) => setForm({ ...form, fullName: e.target.value })} placeholder="Örn. Ayşe Yılmaz" /></label>}
      <label>Kullanıcı adı<input required minLength="3" autoComplete="username" value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} placeholder="kullanici.adi" /></label>
      <label>Parola<input required minLength="8" type="password" autoComplete={mode === 'login' ? 'current-password' : 'new-password'} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder="En az 8 karakter" /></label>
      <button className="primary-button" disabled={saving}>{saving ? 'Bekleyin…' : mode === 'login' ? 'Giriş yap' : 'Hesap oluştur'}</button>
    </form>
    <button className="auth-switch" onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setError(''); }}> {mode === 'login' ? 'İlk kez mi kullanıyorsunuz? Hesap oluşturun' : 'Zaten hesabınız var mı? Giriş yapın'}</button>
  </section></div>;
}

function CameraScanner({ onScan }) {
  const [active, setActive] = useState(false); const [message, setMessage] = useState(''); const videoRef = useRef(null); const controlsRef = useRef(null); const onScanRef = useRef(onScan);
  useEffect(() => { onScanRef.current = onScan; }, [onScan]);
  useEffect(() => { if (!active || !videoRef.current) return undefined; let cancelled = false; setMessage('Kamera izni bekleniyor…'); import('@zxing/browser').then(({ BrowserMultiFormatReader }) => { if (cancelled) return undefined; return new BrowserMultiFormatReader().decodeFromVideoDevice(undefined, videoRef.current, (result, _error, controls) => { controlsRef.current = controls; if (!result || cancelled) return; onScanRef.current(result.getText()); controls.stop(); setActive(false); setMessage('Kod okundu.'); }); }).then((controls) => { if (controls && !cancelled) { controlsRef.current = controls; setMessage('Kodu kameraya gösterin.'); } }).catch(() => { if (!cancelled) { setMessage('Kamera açılamadı. İzni kontrol edin.'); setActive(false); } }); return () => { cancelled = true; controlsRef.current?.stop(); controlsRef.current = null; }; }, [active]);
  return <div className="camera-scanner"><button type="button" className="secondary-button" onClick={() => setActive((value) => !value)}><Barcode size={16} />{active ? 'Kamerayı kapat' : 'Kamerayla okut'}</button>{active && <video ref={videoRef} muted playsInline />}{message && <small>{message}</small>}</div>;
}

function ProductPageLegacy({ products, references, reload, setNotice }) {
  const [form, setForm] = useState({ name: '', stockCode: '', unitName: 'Adet', minimumStock: '0', categoryId: '' }); const [saving, setSaving] = useState(false);
  async function submit(event) { event.preventDefault(); setSaving(true); try { await request('/products', { method: 'POST', body: JSON.stringify({ ...form, categoryId: form.categoryId ? Number(form.categoryId) : null }) }); setNotice({ type: 'success', text: 'Ürün kartı oluşturuldu.' }); setForm({ name: '', stockCode: '', unitName: 'Adet', minimumStock: '0', categoryId: '' }); reload(); } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); } }
  return <><section className="card compact-card"><div><p className="eyebrow">YENİ STOK KARTI</p><h2>Ürün ekle</h2></div><form className="form-grid product-form" onSubmit={submit}><label>Ürün adı<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label><label>Kategori<select value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })}><option value="">Kategori seçin</option>{references.categories?.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label>Stok kodu<input value={form.stockCode} onChange={(e) => setForm({ ...form, stockCode: e.target.value })} /></label><label>Birim<input value={form.unitName} onChange={(e) => setForm({ ...form, unitName: e.target.value })} /></label><label>Minimum stok<input type="number" min="0" step="0.001" value={form.minimumStock} onChange={(e) => setForm({ ...form, minimumStock: e.target.value })} /></label><button className="primary-button" disabled={saving}>{saving ? 'Kaydediliyor…' : 'Ürünü oluştur'}</button></form></section><section className="card"><div className="card-title"><h2>Ürün kartları</h2><span>{products.length} kayıt</span></div><div className="table-wrap"><table><thead><tr><th>Ürün</th><th>Stok kodu</th><th>Birim</th><th>Mevcut stok</th></tr></thead><tbody>{products.map((product) => <tr key={product.id}><td>{product.name}</td><td>{product.stock_code || '—'}</td><td>{product.unit_name}</td><td>{product.current_stock}</td></tr>)}</tbody></table></div></section></>;
}

