  const [form, setForm] = useState({ name: '', stockCode: '', unitName: 'Adet', minimumStock: '0', categoryId: '' });
  const [query, setQuery] = useState(''); const [categoryFilter, setCategoryFilter] = useState(''); const [selected, setSelected] = useState(null); const [codes, setCodes] = useState([]); const [activeCode, setActiveCode] = useState(null); const [qrImage, setQrImage] = useState(''); const [saving, setSaving] = useState(false);
  const filteredProducts = useMemo(() => products.filter((item) => (!categoryFilter || String(item.category_id) === String(categoryFilter) || item.category_name === references.categories?.find((category) => String(category.id) === String(categoryFilter))?.name) && (!query || `${item.name} ${item.stock_code || ''}`.toLocaleLowerCase('tr-TR').includes(query.toLocaleLowerCase('tr-TR')))), [products, categoryFilter, query, references.categories]);
  async function submit(event) { event.preventDefault(); setSaving(true); try { await request('/products', { method: 'POST', body: JSON.stringify({ ...form, categoryId: form.categoryId ? Number(form.categoryId) : null }) }); setNotice({ type: 'success', text: 'Ürün kartı oluşturuldu.' }); setForm({ name: '', stockCode: '', unitName: 'Adet', minimumStock: '0', categoryId: '' }); reload(); } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); } }
  async function showCodes(product) { setSelected(product); setQrImage(''); setActiveCode(null); try { setCodes(await request(`/products/${product.id}/codes`)); } catch (error) { setNotice({ type: 'error', text: error.message }); } }
  async function showQr(code) { setActiveCode(code); setQrImage(code.legacy_qr_base64 ? `data:image/png;base64,${code.legacy_qr_base64}` : await QRCode.toDataURL(code.code_value, { width: 220, margin: 2, color: { dark: '#161b22', light: '#ffffff' } })); }
  return <><section className="card compact-card"><div><p className="eyebrow">YENİ STOK KARTI</p><h2>Ürün ekle</h2></div><form className="form-grid product-form" onSubmit={submit}><label>Ürün adı<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label><label>Kategori<select value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })}><option value="">Kategori seçin</option>{references.categories?.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label>Stok / barkod kodu<input value={form.stockCode} onChange={(e) => setForm({ ...form, stockCode: e.target.value })} /></label><label>Birim<input value={form.unitName} onChange={(e) => setForm({ ...form, unitName: e.target.value })} /></label><label>Minimum stok<input type="number" min="0" step="0.001" value={form.minimumStock} onChange={(e) => setForm({ ...form, minimumStock: e.target.value })} /></label><button className="primary-button" disabled={saving}>{saving ? 'Kaydediliyor…' : 'Ürünü oluştur'}</button></form></section><section className="card"><div className="card-title"><h2>Ürün kartları</h2><span>{filteredProducts.length} / {products.length} kayıt</span></div><div className="table-filters"><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Ürün veya stok kodu ara" /><select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)}><option value="">Tüm kategoriler</option>{references.categories?.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>Ürün</th><th>Kategori</th><th>Stok / barkod</th><th>Mevcut stok</th><th>Kodlar</th></tr></thead><tbody>{filteredProducts.map((product) => <tr key={product.id}><td>{product.name}</td><td>{product.category_name || '—'}</td><td>{product.stock_code || '—'}</td><td>{product.current_stock} {product.unit_name}</td><td><button className="small-button" onClick={() => showCodes(product)}>QR / barkodları</button></td></tr>)}</tbody></table></div></section>{selected && <section className="card code-card"><div className="card-title"><h2>{selected.name} — kodlar</h2><span>{codes.length} tekil kayıt</span></div><p className="muted-text">Eski sistemdeki tekil kayıtlar korunarak yeni QR kimlikleriyle listelenir. Stok/barkod kodu ürün kartında, tekil QR kodları burada görünür.</p><div className="code-layout"><div className="table-wrap"><table><thead><tr><th>Tür</th><th>Kod</th><th>Seri no</th><th>Durum</th><th></th></tr></thead><tbody>{codes.map((code) => <tr key={code.id}><td>{code.code_type}</td><td>{code.code_value}</td><td>{code.serial_number || '—'}</td><td>{code.status}</td><td><button className="small-button" onClick={() => showQr(code)}>QR göster</button></td></tr>)}</tbody></table></div>{qrImage && <div className="code-preview"><img src={qrImage} alt={`${activeCode?.code_value} QR`} /><strong>{activeCode?.code_value}</strong></div>}</div></section>}</>;
