function ProductPage({ products, references, reload, setNotice, navigate }) {
  const [form, setForm] = useState({ name: '', stockCode: '', unitName: 'Adet', minimumStock: '0', categoryId: '' });
  const [query, setQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [detail, setDetail] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [activeCode, setActiveCode] = useState(null);
  const [qrImage, setQrImage] = useState('');
  const [saving, setSaving] = useState(false);
  const filteredProducts = useMemo(() => products.filter((item) => {
    const categoryMatches = !categoryFilter || String(item.category_id) === String(categoryFilter);
    const searchText = `${item.name} ${item.stock_code || ''} ${item.category_name || ''}`.toLocaleLowerCase('tr-TR');
    return categoryMatches && (!query || searchText.includes(query.toLocaleLowerCase('tr-TR')));
  }), [products, categoryFilter, query]);
  const allMovements = useMemo(() => detail ? [...(detail.movements || []), ...(detail.legacyMovements || [])].sort((a, b) => new Date(b.performed_at || 0) - new Date(a.performed_at || 0)) : [], [detail]);

  async function submit(event) {
    event.preventDefault(); setSaving(true);
    try {
      await request('/products', { method: 'POST', body: JSON.stringify({ ...form, categoryId: form.categoryId ? Number(form.categoryId) : null }) });
      setNotice({ type: 'success', text: 'Ürün kartı oluşturuldu.' });
      setForm({ name: '', stockCode: '', unitName: 'Adet', minimumStock: '0', categoryId: '' }); reload();
    } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); }
  }

  async function showDetails(product) {
    setDetailLoading(true); setQrImage(''); setActiveCode(null);
    try { setDetail(await request(`/products/${product.id}/details`)); }
    catch (error) { setNotice({ type: 'error', text: error.message }); }
    finally { setDetailLoading(false); }
  }

  async function showQr(code) {
    setActiveCode(code);
    setQrImage(code.legacy_qr_base64 ? `data:image/png;base64,${code.legacy_qr_base64}` : await QRCode.toDataURL(code.code_value, { width: 220, margin: 2, color: { dark: '#161b22', light: '#ffffff' } }));
  }

  return <>
    <section className="card compact-card">
      <div><p className="eyebrow">YENİ STOK KARTI</p><h2>Ürün ekle</h2></div>
      <form className="form-grid product-form" onSubmit={submit}>
        <label>Ürün adı<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>
        <label>Kategori<select value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })}><option value="">Kategori seçin</option>{references.categories?.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label>
        <label>Stok / barkod kodu<input value={form.stockCode} onChange={(e) => setForm({ ...form, stockCode: e.target.value })} /></label>
        <label>Birim<input value={form.unitName} onChange={(e) => setForm({ ...form, unitName: e.target.value })} /></label>
        <label>Minimum stok<input type="number" min="0" step="0.001" value={form.minimumStock} onChange={(e) => setForm({ ...form, minimumStock: e.target.value })} /></label>
        <button className="primary-button" disabled={saving}>{saving ? 'Kaydediliyor…' : 'Ürünü oluştur'}</button>
      </form>
    </section>

    <section className="card">
      <div className="card-title"><div><p className="eyebrow">STOK KARTLARI</p><h2>Ürün listesi</h2></div><span>{filteredProducts.length} / {products.length} kayıt</span></div>
      <div className="table-filters"><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Ürün, stok kodu veya kategori ara" /><select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)}><option value="">Tüm kategoriler</option>{references.categories?.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div>
      <div className="table-wrap"><table className="product-table"><thead><tr><th>Stok kodu</th><th>Ürün</th><th>Kategori</th><th>Mevcut stok</th><th>QR / barkod</th><th>İşlemler</th></tr></thead><tbody>
        {filteredProducts.length ? filteredProducts.map((product) => <tr key={product.id}>
          <td><strong>{product.stock_code || '—'}</strong><small>Ürün ID: {product.id}</small></td>
          <td><strong>{product.name}</strong><small>{Number(product.minimum_stock) > 0 ? `Minimum stok: ${product.minimum_stock}` : 'Minimum stok yok'}</small></td>
          <td>{product.category_name || 'Kategorisiz'}</td>
          <td><strong>{product.current_stock}</strong> {product.unit_name}</td>
          <td><button className="small-button" onClick={() => showDetails(product)}>Detayları aç</button></td>
          <td><div className="row-actions"><button className="small-button" onClick={() => showDetails(product)}>Tüm işlemler</button><button className="small-button" onClick={() => navigate?.('giris')}>Giriş</button><button className="small-button" onClick={() => navigate?.('cikis')}>Çıkış</button></div></td>
        </tr>) : <tr><td colSpan="6" className="empty-state">Aramanıza uyan ürün bulunamadı.</td></tr>}
      </tbody></table></div>
    </section>

    {detail && <section className="card product-detail-card">
      <div className="card-title"><div><p className="eyebrow">ÜRÜN DETAYI</p><h2>{detail.product.name}</h2><span>{detail.product.stock_code || 'Stok kodu yok'} · {detail.product.category_name || 'Kategorisiz'}</span></div><button className="secondary-button" onClick={() => setDetail(null)}>Detayı kapat</button></div>
      {detailLoading ? <div className="empty-state">Detaylar yükleniyor…</div> : <>
        <div className="product-summary-grid"><div><span>Mevcut stok</span><strong>{detail.product.current_stock} {detail.product.unit_name}</strong></div><div><span>Tekil etiket</span><strong>{detail.product.total_units}</strong></div><div><span>Depoda olan</span><strong>{detail.product.available_units}</strong></div><div><span>Minimum stok</span><strong>{detail.product.minimum_stock}</strong></div></div>
        <div className="detail-heading"><div><h3>Tekil QR / barkod kayıtları</h3><p>Her cihazın durumu, seri numarası ve bulunduğu konum.</p></div><button className="secondary-button" onClick={() => navigate?.('etiket')}>Yeni etiket oluştur</button></div>
        <div className="table-wrap"><table><thead><tr><th>Kod</th><th>Tür</th><th>Seri no</th><th>Durum</th><th>Konum</th><th></th></tr></thead><tbody>{detail.units.length ? detail.units.map((unit) => <tr key={unit.id}><td><strong>{unit.code_value}</strong></td><td>{unit.code_type}</td><td>{unit.serial_number || '—'}</td><td><span className={`unit-status ${unit.status.toLowerCase()}`}>{unitStatusLabels[unit.status] || unit.status}</span></td><td>{unit.warehouse_name ? `${unit.warehouse_name} / ${unit.location_code}` : 'Konum yok'}</td><td><button className="small-button" onClick={() => showQr(unit)}>QR göster</button></td></tr>) : <tr><td colSpan="6" className="empty-state">Bu ürün için tekil QR/barkod kaydı yok.</td></tr>}</tbody></table></div>
        <div className="detail-heading"><div><h3>Tüm stok hareketleri</h3><p>Giriş, çıkış, zimmet, transfer, iade, sipariş ve sayım kayıtları.</p></div><span>{allMovements.length} işlem</span></div>
        <div className="table-wrap"><table className="movement-detail-table"><thead><tr><th>Tarih / işlem no</th><th>İşlem</th><th>Miktar</th><th>Konum</th><th>Neden / teslim alan</th><th>İşlemi yapan</th><th>Belge / not</th></tr></thead><tbody>{allMovements.length ? allMovements.map((movement) => <tr key={movement.id}><td><strong>{formatDate(movement.performed_at)}</strong><small>{movement.movement_no || 'Eski sistem kaydı'}</small></td><td><span className={`status-pill ${movement.movement_type === 'IN' || movement.movement_type === 'RETURN' ? 'success' : movement.movement_type === 'OUT' ? 'danger' : 'warning'}`}>{movementTypeLabels[movement.movement_type] || movement.movement_type}</span><small>{movement.unit_code || 'Toplu hareket'}</small></td><td>{movement.quantity} {detail.product.unit_name}</td><td>{movement.from_location_code || '—'} → {movement.to_location_code || '—'}</td><td><strong>{movement.reason_text}</strong><small>{movement.recipient_name ? `${movement.recipient_name}${movement.recipient_unit ? ` / ${movement.recipient_unit}` : ''}` : movement.supplier_name || '—'}</small></td><td>{movement.performed_by_name || 'Eski kayıt'}</td><td><strong>{movement.document_no || '—'}</strong><small>{movement.note_text || 'Not yok'}</small></td></tr>) : <tr><td colSpan="7" className="empty-state">Bu ürün için henüz hareket kaydı yok.</td></tr>}</tbody></table></div>
      </>}
      {qrImage && <div className="code-preview inline-code-preview"><img src={qrImage} alt={`${activeCode?.code_value} QR`} /><strong>{activeCode?.code_value}</strong></div>}
    </section>}
  </>;
}

function MovementPageLegacy({ type, references, reload, setNotice }) {
  const [form, setForm] = useState({ productId: '', quantity: '1', countedQuantity: '', fromLocationId: '', toLocationId: '', reason: '', recipientName: '', recipientUnit: '', documentNo: '', note: '', unitCode: '', supplierId: '' }); const [saving, setSaving] = useState(false); const locations = references.locations || []; const isCount = type === 'COUNT'; const needsFrom = type === 'OUT' || type === 'TRANSFER'; const needsTo = type !== 'OUT';
  async function submit(event) { event.preventDefault(); setSaving(true); try { const payload = { ...form, type, productId: Number(form.productId), quantity: isCount ? 1 : Number(form.quantity), countedQuantity: isCount ? Number(form.countedQuantity) : undefined, fromLocationId: form.fromLocationId ? Number(form.fromLocationId) : null, toLocationId: form.toLocationId ? Number(form.toLocationId) : null, supplierId: form.supplierId ? Number(form.supplierId) : null }; await request('/movements', { method: 'POST', body: JSON.stringify(payload) }); setNotice({ type: 'success', text: `${flowLabels[type]} kaydedildi.` }); setForm({ productId: '', quantity: '1', countedQuantity: '', fromLocationId: '', toLocationId: '', reason: '', recipientName: '', recipientUnit: '', documentNo: '', note: '', unitCode: '', supplierId: '' }); reload(); } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); } }
  return <section className="card workflow-card"><div className="workflow-intro"><p className="eyebrow">KAYITLI STOK HAREKETİ</p><h2>{flowLabels[type]}</h2><p>{type === 'OUT' ? 'Teslim alan kişi/birim ve çıkış nedenini kaydetmeden stok düşülmez.' : 'İşlem, konum stok bakiyesi ve hareket günlüğünü aynı anda günceller.'}</p></div><form className="form-grid" onSubmit={submit}><label>Ürün<select required value={form.productId} onChange={(e) => setForm({ ...form, productId: e.target.value })}><option value="">Ürün seçin</option>{references.products?.map((product) => <option key={product.id} value={product.id}>{product.name} {product.stock_code ? `(${product.stock_code})` : ''}</option>)}</select></label>{needsFrom && <label>Kaynak konum<select required value={form.fromLocationId} onChange={(e) => setForm({ ...form, fromLocationId: e.target.value })}><option value="">Konum seçin</option>{locations.map((location) => <option key={location.id} value={location.id}>{location.warehouse_name} / {location.code}</option>)}</select></label>}{needsTo && <label>{type === 'TRANSFER' ? 'Hedef konum' : 'Konum'}<select required value={form.toLocationId} onChange={(e) => setForm({ ...form, toLocationId: e.target.value })}><option value="">Konum seçin</option>{locations.map((location) => <option key={location.id} value={location.id}>{location.warehouse_name} / {location.code}</option>)}</select></label>}{isCount ? <label>Sayılan miktar<input required type="number" min="0" step="0.001" value={form.countedQuantity} onChange={(e) => setForm({ ...form, countedQuantity: e.target.value })} /></label> : <label>Miktar<input required type="number" min="0.001" step="0.001" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} /></label>}<label>İşlem nedeni<input required value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} placeholder={type === 'IN' ? 'Örn. Mal kabul' : type === 'OUT' ? 'Örn. Kurulum için sevk' : 'Örn. Periyodik sayım'} /></label>{type === 'OUT' && <><label>Teslim alan kişi<input required value={form.recipientName} onChange={(e) => setForm({ ...form, recipientName: e.target.value })} /></label><label>Teslim alan birim<input value={form.recipientUnit} onChange={(e) => setForm({ ...form, recipientUnit: e.target.value })} /></label></>}{/* Both phone camera and keyboard-wedge terminal fill this same field. */}<label>QR / barkod (el terminali veya telefon)<input autoFocus autoComplete="off" inputMode="none" value={form.unitCode} onKeyDown={(event) => { if (event.key === 'Enter') event.preventDefault(); }} onChange={(e) => setForm({ ...form, unitCode: e.target.value })} placeholder="El terminalini okutun veya kamera kullanın" /><CameraScanner onScan={(code) => setForm((current) => ({ ...current, unitCode: code }))} /></label><label>Belge no (opsiyonel)<input value={form.documentNo} onChange={(e) => setForm({ ...form, documentNo: e.target.value })} /></label><label className="wide">Açıklama (opsiyonel)<textarea value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} /></label><button className="primary-button" disabled={saving}>{saving ? 'Kaydediliyor…' : 'Hareketi kaydet'}</button></form></section>;
}

function MovementPage({ type, references, reload, setNotice }) {
  const [form, setForm] = useState({ productId: '', quantity: '1', countedQuantity: '', fromLocationId: '', toLocationId: '', reason: '', recipientName: '', recipientUnit: '', documentNo: '', note: '', unitCode: '', supplierId: '' });
  const [saving, setSaving] = useState(false);
  const locations = references.locations || [];
  const isCount = type === 'COUNT';
  const needsFrom = type === 'OUT' || type === 'TRANSFER';
  const needsTo = type !== 'OUT';
  async function submit(event) {
    event.preventDefault(); setSaving(true);
    try {
      const payload = { ...form, type, productId: Number(form.productId), quantity: isCount ? 1 : Number(form.quantity), countedQuantity: isCount ? Number(form.countedQuantity) : undefined, fromLocationId: form.fromLocationId ? Number(form.fromLocationId) : null, toLocationId: form.toLocationId ? Number(form.toLocationId) : null, supplierId: form.supplierId ? Number(form.supplierId) : null };
      await request('/movements', { method: 'POST', body: JSON.stringify(payload) });
      setNotice({ type: 'success', text: `${flowLabels[type]} kaydedildi.` });
      setForm({ productId: '', quantity: '1', countedQuantity: '', fromLocationId: '', toLocationId: '', reason: '', recipientName: '', recipientUnit: '', documentNo: '', note: '', unitCode: '', supplierId: '' }); reload();
    } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); }
  }
  return <section className="card workflow-card"><div className="workflow-intro"><p className="eyebrow">KAYITLI STOK HAREKETİ</p><h2>{flowLabels[type]}</h2><p>{type === 'OUT' ? 'Teslim alan kişi/birim ve çıkış nedenini kaydetmeden stok düşülmez.' : 'İşlem, konum stok bakiyesi ve hareket günlüğünü aynı anda günceller.'}</p></div><form className="form-grid" onSubmit={submit}>
    <label>Ürün<select required value={form.productId} onChange={(e) => setForm({ ...form, productId: e.target.value })}><option value="">Ürün seçin</option>{references.products?.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
    {needsFrom && <label>Kaynak konum<select required value={form.fromLocationId} onChange={(e) => setForm({ ...form, fromLocationId: e.target.value })}><option value="">Konum seçin</option>{locations.map((item) => <option key={item.id} value={item.id}>{item.warehouse_name} / {item.code}</option>)}</select></label>}
    {needsTo && <label>{type === 'TRANSFER' ? 'Hedef konum' : 'Konum'}<select required value={form.toLocationId} onChange={(e) => setForm({ ...form, toLocationId: e.target.value })}><option value="">Konum seçin</option>{locations.map((item) => <option key={item.id} value={item.id}>{item.warehouse_name} / {item.code}</option>)}</select></label>}
    {isCount ? <label>Sayılan miktar<input required type="number" min="0" step="0.001" value={form.countedQuantity} onChange={(e) => setForm({ ...form, countedQuantity: e.target.value })} /></label> : <label>Miktar<input required type="number" min="0.001" step="0.001" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} /></label>}
    {type === 'IN' && <label>Tedarikçi<select value={form.supplierId} onChange={(e) => setForm({ ...form, supplierId: e.target.value })}><option value="">Tedarikçi seçin</option>{references.suppliers?.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>}
    <label>İşlem nedeni<input required value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} /></label>
    {type === 'OUT' && <><label>Teslim alan kişi<input required value={form.recipientName} onChange={(e) => setForm({ ...form, recipientName: e.target.value })} /></label><label>Teslim alan birim<input value={form.recipientUnit} onChange={(e) => setForm({ ...form, recipientUnit: e.target.value })} /></label></>}
    <label>QR / barkod (el terminali veya telefon)<input autoFocus autoComplete="off" inputMode="none" value={form.unitCode} onKeyDown={(event) => { if (event.key === 'Enter') event.preventDefault(); }} onChange={(e) => setForm({ ...form, unitCode: e.target.value })} placeholder="El terminalini okutun veya kamera kullanın" /><CameraScanner onScan={(code) => setForm((current) => ({ ...current, unitCode: code }))} /></label>
    <label>Belge no (opsiyonel)<input value={form.documentNo} onChange={(e) => setForm({ ...form, documentNo: e.target.value })} /></label><label className="wide">Açıklama (opsiyonel)<textarea value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} /></label><button className="primary-button" disabled={saving}>{saving ? 'Kaydediliyor…' : 'Hareketi kaydet'}</button>
  </form></section>;
}

function LabelPage({ references, reload, setNotice }) {
  const [form, setForm] = useState({ productId: '', codeValue: '', serialNumber: '', locationId: '' }); const [image, setImage] = useState(''); const [saving, setSaving] = useState(false);
  async function create(event) { event.preventDefault(); if (!form.codeValue.trim()) return; setImage(await QRCode.toDataURL(form.codeValue.trim(), { width: 280, margin: 2, color: { dark: '#161b22', light: '#ffffff' } })); }
  async function save() { setSaving(true); try { await request('/inventory-units', { method: 'POST', body: JSON.stringify({ ...form, productId: Number(form.productId), locationId: form.locationId ? Number(form.locationId) : null, codeType: 'QR' }) }); setNotice({ type: 'success', text: 'Tekil cihaz etiketi kaydedildi.' }); reload(); } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); } }
  return <section className="card label-workspace"><div><p className="eyebrow">QR VE BARKOD</p><h2>Etiket merkezi</h2><p>Önce ürün seçin, cihaz kodunu üretin veya okutun. Etiketi kaydettikten sonra giriş/çıkış formlarında okutabilirsiniz.</p><form onSubmit={create} className="form-grid"><label>Ürün<select required value={form.productId} onChange={(e) => setForm({ ...form, productId: e.target.value })}><option value="">Ürün seçin</option>{references.products?.map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></label><label>Etiket kodu<input required value={form.codeValue} onChange={(e) => setForm({ ...form, codeValue: e.target.value })} placeholder="Örn. BRF-CIH-000123" /><CameraScanner onScan={(code) => setForm((current) => ({ ...current, codeValue: code }))} /></label><label>Seri no (opsiyonel)<input value={form.serialNumber} onChange={(e) => setForm({ ...form, serialNumber: e.target.value })} /></label><label>Konum (opsiyonel)<select value={form.locationId} onChange={(e) => setForm({ ...form, locationId: e.target.value })}><option value="">Konum seçin</option>{references.locations?.map((location) => <option key={location.id} value={location.id}>{location.warehouse_name} / {location.code}</option>)}</select></label><div className="button-row"><button className="primary-button" type="submit">QR oluştur</button>{image && <button className="secondary-button" type="button" onClick={save} disabled={saving}>{saving ? 'Kaydediliyor…' : 'Etiketi kaydet'}</button>}</div></form></div>{image ? <div className="qr-result"><img src={image} alt="Oluşturulan QR kod" /><strong>{form.codeValue}</strong></div> : <div className="qr-placeholder"><QrCode size={52} /><span>Etiket önizlemesi</span></div>}</section>;
}

function LocationPage({ locations, reload, setNotice }) {
  const [warehouse, setWarehouse] = useState({ code: '', name: '' }); const [location, setLocation] = useState({ warehouseId: '', code: '', name: '' }); const warehouses = useMemo(() => Array.from(new Map(locations.map((item) => [item.warehouse_id, { id: item.warehouse_id, name: item.warehouse_name, code: item.warehouse_code }])).values()), [locations]);
  async function submitWarehouse(event) { event.preventDefault(); try { await request('/warehouses', { method: 'POST', body: JSON.stringify(warehouse) }); setNotice({ type: 'success', text: 'Depo oluşturuldu.' }); setWarehouse({ code: '', name: '' }); reload(); } catch (error) { setNotice({ type: 'error', text: error.message }); } }
  async function submitLocation(event) { event.preventDefault(); try { await request('/locations', { method: 'POST', body: JSON.stringify({ ...location, warehouseId: Number(location.warehouseId) }) }); setNotice({ type: 'success', text: 'Raf/alan oluşturuldu.' }); setLocation({ warehouseId: '', code: '', name: '' }); reload(); } catch (error) { setNotice({ type: 'error', text: error.message }); } }
  return <><section className="two-cards"><form className="card form-grid" onSubmit={submitWarehouse}><div><p className="eyebrow">TANIM</p><h2>Yeni depo</h2></div><label>Depo kodu<input required value={warehouse.code} onChange={(e) => setWarehouse({ ...warehouse, code: e.target.value })} placeholder="Örn. IST-01" /></label><label>Depo adı<input required value={warehouse.name} onChange={(e) => setWarehouse({ ...warehouse, name: e.target.value })} /></label><button className="primary-button">Depoyu ekle</button></form><form className="card form-grid" onSubmit={submitLocation}><div><p className="eyebrow">KONUM</p><h2>Yeni raf / alan</h2></div><label>Depo<select required value={location.warehouseId} onChange={(e) => setLocation({ ...location, warehouseId: e.target.value })}><option value="">Depo seçin</option>{warehouses.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Konum kodu<input required value={location.code} onChange={(e) => setLocation({ ...location, code: e.target.value })} placeholder="Örn. A-01-02" /></label><label>Konum adı<input required value={location.name} onChange={(e) => setLocation({ ...location, name: e.target.value })} /></label><button className="primary-button">Konumu ekle</button></form></section><section className="card"><div className="card-title"><h2>Depo konumları</h2><span>{locations.length} konum</span></div><div className="table-wrap"><table><thead><tr><th>Depo</th><th>Kod</th><th>Alan adı</th></tr></thead><tbody>{locations.map((item) => <tr key={item.id}><td>{item.warehouse_name}</td><td>{item.code}</td><td>{item.name}</td></tr>)}</tbody></table></div></section></>;
}

function ManagementPage({ references, reload, setNotice }) {
  const [tab, setTab] = useState('categories');
  const [categoryName, setCategoryName] = useState('');
  const [supplierForm, setSupplierForm] = useState({ name: '', contact: '', note: '' });
  const [customerForm, setCustomerForm] = useState({ name: '', note: '' });
  const [orderForm, setOrderForm] = useState({ customerId: '', productId: '', quantity: '1', orderDate: new Date().toISOString().slice(0, 10), note: '' });
  const [orders, setOrders] = useState([]); const [loans, setLoans] = useState([]); const [supplies, setSupplies] = useState([]); const [report, setReport] = useState([]); const [returnLocation, setReturnLocation] = useState(references.locations?.[0]?.id || '');
  const tabs = [['categories', 'Kategoriler'], ['suppliers', 'Tedarikçiler'], ['customers', 'Müşteriler'], ['orders', 'Siparişler'], ['loans', 'Emanetler'], ['reports', 'Raporlar']];
  async function loadManagement() { try { const [orderRows, loanRows, supplyRows, reportRows] = await Promise.all([request('/orders'), request('/loans'), request('/supplies'), request('/reports/stock')]); setOrders(orderRows); setLoans(loanRows); setSupplies(supplyRows); setReport(reportRows); } catch (error) { setNotice({ type: 'error', text: error.message }); } }
  useEffect(() => { loadManagement(); }, []);
  useEffect(() => { if (!returnLocation && references.locations?.[0]) setReturnLocation(references.locations[0].id); }, [references.locations, returnLocation]);
  async function simpleCreate(path, payload, message, reset) { try { await request(path, { method: 'POST', body: JSON.stringify(payload) }); setNotice({ type: 'success', text: message }); reset(); reload(); loadManagement(); } catch (error) { setNotice({ type: 'error', text: error.message }); } }
  async function createOrder(event) { event.preventDefault(); await simpleCreate('/orders', { customerId: orderForm.customerId ? Number(orderForm.customerId) : null, orderDate: orderForm.orderDate, note: orderForm.note, items: [{ productId: Number(orderForm.productId), quantity: Number(orderForm.quantity) }] }, 'Sipariş oluşturuldu.', () => setOrderForm({ customerId: '', productId: '', quantity: '1', orderDate: new Date().toISOString().slice(0, 10), note: '' })); }
  async function returnLoan(id) { try { await request(`/loans/${id}/return`, { method: 'PUT', body: JSON.stringify({ toLocationId: Number(returnLocation) }) }); setNotice({ type: 'success', text: 'Emanet teslim alındı ve stoğa döndü.' }); reload(); loadManagement(); } catch (error) { setNotice({ type: 'error', text: error.message }); } }
  function downloadReport() { const header = 'Ürün;Stok kodu;Kategori;Mevcut stok;Minimum stok\n'; const body = report.map((row) => [row.name, row.stock_code || '', row.category_name || '', row.current_stock, row.minimum_stock].join(';')).join('\n'); const url = URL.createObjectURL(new Blob([header + body], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = 'barfas-stok-raporu.csv'; link.click(); URL.revokeObjectURL(url); }
  return <section className="management"><div className="management-tabs">{tabs.map(([key, label]) => <button key={key} className={tab === key ? 'management-tab active' : 'management-tab'} onClick={() => setTab(key)}>{label}</button>)}</div>{tab === 'categories' && <div className="management-pane"><form className="inline-form" onSubmit={(event) => { event.preventDefault(); simpleCreate('/categories', { name: categoryName }, 'Kategori oluşturuldu.', () => setCategoryName('')); }}><label>Yeni kategori<input required value={categoryName} onChange={(e) => setCategoryName(e.target.value)} placeholder="Örn. Sensörler" /></label><button className="primary-button">Ekle</button></form><div className="simple-list">{references.categories?.map((item) => <span key={item.id}>{item.name}</span>)}</div></div>}{tab === 'suppliers' && <div className="management-pane"><form className="form-grid management-form" onSubmit={(event) => { event.preventDefault(); simpleCreate('/suppliers', supplierForm, 'Tedarikçi oluşturuldu.', () => setSupplierForm({ name: '', contact: '', note: '' })); }}><label>Tedarikçi adı<input required value={supplierForm.name} onChange={(e) => setSupplierForm({ ...supplierForm, name: e.target.value })} /></label><label>İletişim<input value={supplierForm.contact} onChange={(e) => setSupplierForm({ ...supplierForm, contact: e.target.value })} /></label><label className="wide">Not<input value={supplierForm.note} onChange={(e) => setSupplierForm({ ...supplierForm, note: e.target.value })} /></label><button className="primary-button">Tedarikçi ekle</button></form><h3>Tedarik geçmişi</h3><div className="table-wrap"><table><thead><tr><th>Tedarikçi</th><th>Ürün</th><th>Miktar</th><th>Tarih</th></tr></thead><tbody>{supplies.map((row) => <tr key={row.id}><td>{row.supplier_name}</td><td>{row.product_name || '—'}</td><td>{row.quantity} {row.unit_name || ''}</td><td>{row.supplied_at ? new Date(row.supplied_at).toLocaleDateString('tr-TR') : '—'}</td></tr>)}</tbody></table></div></div>}{tab === 'customers' && <div className="management-pane"><form className="form-grid management-form" onSubmit={(event) => { event.preventDefault(); simpleCreate('/customers', customerForm, 'Müşteri oluşturuldu.', () => setCustomerForm({ name: '', note: '' })); }}><label>Müşteri adı<input required value={customerForm.name} onChange={(e) => setCustomerForm({ ...customerForm, name: e.target.value })} /></label><label>Not<input value={customerForm.note} onChange={(e) => setCustomerForm({ ...customerForm, note: e.target.value })} /></label><button className="primary-button">Müşteri ekle</button></form><div className="simple-list">{references.customers?.map((item) => <span key={item.id}>{item.name}</span>)}</div></div>}{tab === 'orders' && <div className="management-pane"><form className="form-grid management-form" onSubmit={createOrder}><label>Müşteri<select value={orderForm.customerId} onChange={(e) => setOrderForm({ ...orderForm, customerId: e.target.value })}><option value="">Müşteri seçin</option>{references.customers?.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Ürün<select required value={orderForm.productId} onChange={(e) => setOrderForm({ ...orderForm, productId: e.target.value })}><option value="">Ürün seçin</option>{references.products?.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Miktar<input required type="number" min="0.001" step="0.001" value={orderForm.quantity} onChange={(e) => setOrderForm({ ...orderForm, quantity: e.target.value })} /></label><label>Sipariş tarihi<input required type="date" value={orderForm.orderDate} onChange={(e) => setOrderForm({ ...orderForm, orderDate: e.target.value })} /></label><label className="wide">Açıklama<input value={orderForm.note} onChange={(e) => setOrderForm({ ...orderForm, note: e.target.value })} /></label><button className="primary-button">Sipariş oluştur</button></form><div className="table-wrap"><table><thead><tr><th>Sipariş</th><th>Müşteri</th><th>Tarih</th><th>Durum</th><th>Kalem</th></tr></thead><tbody>{orders.map((row) => <tr key={row.id}><td>{row.order_no}</td><td>{row.customer_name || '—'}</td><td>{new Date(row.order_date).toLocaleDateString('tr-TR')}</td><td>{row.status}</td><td>{row.item_count}</td></tr>)}</tbody></table></div></div>}{tab === 'loans' && <div className="management-pane"><div className="inline-form"><label>İade konumu<select value={returnLocation} onChange={(e) => setReturnLocation(e.target.value)}>{references.locations?.map((item) => <option key={item.id} value={item.id}>{item.warehouse_name} / {item.code}</option>)}</select></label></div><div className="table-wrap"><table><thead><tr><th>Ürün</th><th>Tekil kod</th><th>Teslim alan</th><th>Miktar</th><th>Durum</th><th></th></tr></thead><tbody>{loans.map((row) => <tr key={row.id}><td>{row.product_name}</td><td>{row.unit_code || 'Toplu çıkış'}</td><td>{row.recipient_name}{row.recipient_unit ? ` / ${row.recipient_unit}` : ''}</td><td>{row.quantity}</td><td>{row.status === 'ACTIVE' ? 'Aktif' : 'Teslim alındı'}</td><td>{row.status === 'ACTIVE' && <button className="small-button" onClick={() => returnLoan(row.id)}>Teslim al</button>}</td></tr>)}</tbody></table></div></div>}{tab === 'reports' && <div className="management-pane"><div className="report-toolbar"><p>Ürün bazında güncel stok ve minimum stok karşılaştırması.</p><button className="secondary-button" onClick={downloadReport}>CSV indir</button></div><div className="table-wrap"><table><thead><tr><th>Ürün</th><th>Kategori</th><th>Mevcut</th><th>Minimum</th></tr></thead><tbody>{report.map((row) => <tr key={row.name}><td>{row.name}</td><td>{row.category_name || '—'}</td><td>{row.current_stock}</td><td>{row.minimum_stock}</td></tr>)}</tbody></table></div></div>}</section>;
}

function DashboardOverviewLegacy({ summary, movements, navigate }) {
  const quickActions = [['giris', 'Stok girişi', 'Depoya ürün kabul et'], ['cikis', 'Çıkış / zimmet', 'Teslim ve çıkış kaydı'], ['transfer', 'Depo transferi', 'Konum değişikliği'], ['etiket', 'Etiket merkezi', 'QR etiketi oluştur']];
  return <><div className="quick-actions">{quickActions.map(([key, label, helper]) => <button key={key} className="quick-action" onClick={() => navigate(key)}><span className="quick-icon q-red"><PackagePlus size={19} /></span><span className="quick-text"><b>{label}</b><small>{helper}</small></span><ArrowLeftRight size={15} className="quick-arrow" /></button>)}</div><section className="metric-grid"><Metric label="Aktif ürün" value={summary?.product_count} /><Metric label="Depodaki tekil cihaz" value={summary?.ready_unit_count} /><Metric label="Bugünkü hareket" value={summary?.today_movement_count} /><Metric label="Kritik stok" value={summary?.low_stock_count} alert /></section><div className="dashboard-panels"><section className="card dashboard-callout"><p className="eyebrow">BARFAS DEPO MERKEZİ</p><h2>Stok hareketlerini tek akışta yönetin.</h2><p>Ürünü bulun, kodu okutun ve hareketi neden/konum bilgisiyle kaydedin. Her işlem geçmişte izlenebilir kalır.</p><div className="dashboard-steps"><span><b>01</b>Ürün</span><span><b>02</b>Konum</span><span><b>03</b>Hareket</span></div></section><section className="card dashboard-side"><div className="card-title"><h2>Bugünkü özet</h2><span>Canlı veri</span></div><div className="summary-list"><div><span>Son hareket</span><strong>{movements[0] ? flowLabels[movements[0].movement_type] || movements[0].movement_type : 'Henüz yok'}</strong></div><div><span>Son ürün</span><strong>{movements[0]?.product_name || 'Henüz yok'}</strong></div><div><span>Kritik stok</span><strong className={Number(summary?.low_stock_count) > 0 ? 'summary-danger' : ''}>{summary?.low_stock_count ?? '—'}</strong></div></div></section></div><section className="card recent-card"><div className="card-title"><h2>Son hareketler</h2><span>{movements.length} kayıt</span></div><div className="table-wrap"><table><thead><tr><th>İşlem</th><th>Ürün</th><th>Miktar</th><th>Neden</th><th>Tarih</th></tr></thead><tbody>{movements.length ? movements.slice(0, 8).map((item) => <tr key={item.id}><td>{flowLabels[item.movement_type] || item.movement_type}</td><td>{item.product_name}</td><td>{item.quantity}</td><td>{item.reason_text}</td><td>{new Date(item.performed_at).toLocaleString('tr-TR')}</td></tr>) : <tr><td colSpan="5" className="empty-cell">Henüz hareket kaydı yok.</td></tr>}</tbody></table></div></section></>;
}

function DashboardOverview({ summary, movements, navigate }) {
  const quickActions = [
    ['giris', 'Stok girişi', 'Depoya ürün kabul et'],
    ['cikis', 'Çıkış / zimmet', 'Teslim ve çıkış kaydı'],
    ['transfer', 'Depo transferi', 'Konum değişikliği'],
    ['etiket', 'Etiket merkezi', 'QR etiketi oluştur'],
  ];
  return <>
    <div className="quick-actions">{quickActions.map(([key, label, helper]) => <button key={key} className="quick-action" onClick={() => navigate(key)}><span className="quick-icon q-red"><PackagePlus size={19} /></span><span className="quick-text"><b>{label}</b><small>{helper}</small></span><ArrowLeftRight size={15} className="quick-arrow" /></button>)}</div>
    <section className="metric-grid"><Metric label="Aktif ürün" value={summary?.product_count} /><Metric label="Depodaki tekil cihaz" value={summary?.ready_unit_count} /><Metric label="Bugünkü hareket" value={summary?.today_movement_count} /><Metric label="Kritik stok" value={summary?.low_stock_count} alert /></section>
    <section className="card recent-card"><div className="card-title"><h2>Son hareketler</h2><span>{movements.length} kayıt</span></div><div className="table-wrap"><table><thead><tr><th>İşlem</th><th>Ürün</th><th>Miktar</th><th>Neden</th><th>İşlemi yapan</th><th>Tarih</th></tr></thead><tbody>{movements.length ? movements.slice(0, 8).map((item) => <tr key={item.id}><td>{flowLabels[item.movement_type] || item.movement_type}</td><td>{item.product_name}</td><td>{item.quantity}</td><td>{item.reason_text}</td><td>{item.performed_by_name || 'Eski kayıt'}</td><td>{formatDate(item.performed_at)}</td></tr>) : <tr><td colSpan="6" className="empty-cell">Henüz hareket kaydı yok.</td></tr>}</tbody></table></div></section>
  </>;
}

function AppLegacy() {
  const [page, setPage] = useState('panel'); const [menuOpen, setMenuOpen] = useState(false); const [summary, setSummary] = useState(null); const [products, setProducts] = useState([]); const [references, setReferences] = useState({ products: [], locations: [] }); const [locations, setLocations] = useState([]); const [movements, setMovements] = useState([]); const [apiStatus, setApiStatus] = useState('Yükleniyor'); const [notice, setNotice] = useState(null); const title = useMemo(() => navigation.find(([key]) => key === page)?.[1] || 'Panel', [page]);
  async function reload() { try { const [health, dashboard, productList, referenceData, locationList, movementList] = await Promise.all([request('/health'), request('/dashboard'), request('/products'), request('/reference-data'), request('/locations'), request('/movements')]); setApiStatus(health.database === 'connected' ? 'Bağlı' : 'Veritabanı bekleniyor'); setSummary(dashboard); setProducts(productList); setReferences(referenceData); setLocations(locationList); setMovements(movementList); } catch { setApiStatus('Veritabanı bağlantısı bekleniyor'); } }
  useEffect(() => { reload(); }, []);
  return <div className="app-shell"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menüyü aç"><Menu size={22} /></button><div className="brand"><span className="brand-mark">B</span><span>Barfas <em>Depo</em></span></div><div className="connection"><i className={apiStatus === 'Bağlı' ? 'online' : ''} />{apiStatus}</div></header><aside className={`sidebar ${menuOpen ? 'sidebar-open' : ''}`}><p className="nav-heading">OPERASYON</p>{navigation.map(([key, label, Icon]) => <button key={key} className={page === key ? 'nav-item active' : 'nav-item'} onClick={() => { setPage(key); setMenuOpen(false); setNotice(null); }}><Icon size={19} />{label}</button>)}<div className="sidebar-help"><MapPin size={18} /><span>Her hareket, neden ve konumuyla kaydedilir.</span></div></aside><main className="content"><div className="page-heading"><div><p className="eyebrow">DEPO YÖNETİMİ</p><h1>{title}</h1></div></div><Notice notice={notice} />{page === 'panel' && <><section className="metric-grid"><Metric label="Aktif ürün" value={summary?.product_count} /><Metric label="Depodaki tekil cihaz" value={summary?.ready_unit_count} /><Metric label="Bugünkü hareket" value={summary?.today_movement_count} /><Metric label="Kritik stok" value={summary?.low_stock_count} alert /></section><section className="card recent-card"><div className="card-title"><h2>Son hareketler</h2><span>{movements.length} kayıt</span></div><div className="table-wrap"><table><thead><tr><th>İşlem</th><th>Ürün</th><th>Miktar</th><th>Neden</th><th>Tarih</th></tr></thead><tbody>{movements.length ? movements.slice(0, 8).map((item) => <tr key={item.id}><td>{flowLabels[item.movement_type] || item.movement_type}</td><td>{item.product_name}</td><td>{item.quantity}</td><td>{item.reason_text}</td><td>{new Date(item.performed_at).toLocaleString('tr-TR')}</td></tr>) : <tr><td colSpan="5" className="empty-cell">Henüz hareket kaydı yok.</td></tr>}</tbody></table></div></section></>}{page === 'urunler' && <ProductPage products={products} references={references} reload={reload} setNotice={setNotice} />}{page === 'etiket' && <LabelPage references={references} reload={reload} setNotice={setNotice} />}{page === 'konumlar' && <LocationPage locations={locations} reload={reload} setNotice={setNotice} />}{page === 'yonetim' && <ManagementPage references={references} reload={reload} setNotice={setNotice} />}{page === 'giris' && <MovementPage type="IN" references={references} reload={reload} setNotice={setNotice} />}{page === 'cikis' && <MovementPage type="OUT" references={references} reload={reload} setNotice={setNotice} />}{page === 'transfer' && <MovementPage type="TRANSFER" references={references} reload={reload} setNotice={setNotice} />}{page === 'iade' && <MovementPage type="RETURN" references={references} reload={reload} setNotice={setNotice} />}{page === 'sayim' && <MovementPage type="COUNT" references={references} reload={reload} setNotice={setNotice} />}</main></div>;
}
function App() {
  const [user, setUser] = useState(null); const [authReady, setAuthReady] = useState(false);
  useEffect(() => {
    if (!localStorage.getItem('barfas_auth_token')) { setAuthReady(true); return; }
    request('/auth/me').then(({ user: authenticatedUser }) => setUser(authenticatedUser)).catch(() => localStorage.removeItem('barfas_auth_token')).finally(() => setAuthReady(true));
  }, []);
  useEffect(() => {
    if (!user) return undefined;
    const header = document.querySelector('.topbar');
    if (!header) return undefined;
    const account = document.createElement('div'); account.className = 'topbar-user';
    const name = document.createElement('span'); name.textContent = user.fullName;
    const logoutButton = document.createElement('button'); logoutButton.className = 'logout-button'; logoutButton.type = 'button'; logoutButton.textContent = 'Çıkış'; logoutButton.onclick = () => { request('/auth/logout', { method: 'POST' }).catch(() => {}).finally(() => { localStorage.removeItem('barfas_auth_token'); setUser(null); }); };
    account.append(name, logoutButton); header.insertBefore(account, header.querySelector('.connection'));
    return () => account.remove();
  }, [user]);
  useEffect(() => {
    if (!user) return undefined;
    const sidebar = document.querySelector('.sidebar');
    if (!sidebar) return undefined;
    const profile = document.createElement('div'); profile.className = 'sidebar-profile';
    const avatar = document.createElement('span'); avatar.className = 'sidebar-profile-avatar'; avatar.textContent = (user.fullName || user.username).slice(0, 1).toUpperCase();
    const details = document.createElement('div'); details.className = 'sidebar-profile-details';
    const fullName = document.createElement('strong'); fullName.textContent = user.fullName;
    const username = document.createElement('small'); username.textContent = `@${user.username}`;
    const settings = document.createElement('button'); settings.type = 'button'; settings.className = 'sidebar-profile-settings'; settings.textContent = 'Profil ayarları';
    details.append(fullName, username, settings); profile.append(avatar, details); sidebar.append(profile);
    let modal;
    function closeModal() { modal?.remove(); modal = null; }
    function openModal() {
      if (modal) return;
      modal = document.createElement('div'); modal.className = 'profile-modal-backdrop';
      modal.innerHTML = `<section class="profile-modal" role="dialog" aria-modal="true" aria-label="Profil ayarları"><div class="profile-modal-head"><div><p class="eyebrow">HESABIM</p><h2>Profil ayarları</h2></div><button type="button" class="profile-modal-close" aria-label="Kapat">×</button></div><p class="profile-modal-intro">Adınızı veya giriş parolanızı buradan güncelleyebilirsiniz.</p><form class="profile-form"><label>Ad soyad<input name="fullName" required minlength="2" maxlength="100"></label><label>Mevcut parola<input name="currentPassword" type="password" autocomplete="current-password"></label><label>Yeni parola <small>(değiştirmek istemiyorsanız boş bırakın)</small><input name="newPassword" type="password" minlength="8" autocomplete="new-password"></label><div class="profile-form-message"></div><div class="profile-form-actions"><button type="button" class="secondary-button profile-cancel">Vazgeç</button><button type="submit" class="primary-button">Kaydet</button></div></form></section>`;
      modal.querySelector('[name="fullName"]').value = user.fullName;
      modal.querySelector('.profile-modal-close').onclick = closeModal;
      modal.querySelector('.profile-cancel').onclick = closeModal;
      modal.onclick = (event) => { if (event.target === modal) closeModal(); };
      modal.querySelector('form').onsubmit = async (event) => {
        event.preventDefault();
        const form = new FormData(event.currentTarget); const message = modal.querySelector('.profile-form-message'); const submitButton = modal.querySelector('button[type="submit"]');
        submitButton.disabled = true; message.textContent = '';
        try {
          const result = await request('/auth/profile', { method: 'PUT', body: JSON.stringify({ fullName: form.get('fullName'), currentPassword: form.get('currentPassword') || undefined, newPassword: form.get('newPassword') || undefined }) });
          setUser(result.user); closeModal();
        } catch (error) { message.textContent = error.message; } finally { submitButton.disabled = false; }
      };
      document.body.append(modal); modal.querySelector('[name="fullName"]').focus();
    }
    profile.onclick = openModal; settings.onclick = (event) => { event.stopPropagation(); openModal(); };
    return () => { profile.remove(); closeModal(); };
  }, [user]);
  const [page, setPage] = useState('panel'); const [menuOpen, setMenuOpen] = useState(false); const [summary, setSummary] = useState(null); const [products, setProducts] = useState([]); const [references, setReferences] = useState({ products: [], locations: [], categories: [], suppliers: [], customers: [] }); const [locations, setLocations] = useState([]); const [movements, setMovements] = useState([]); const [apiStatus, setApiStatus] = useState('Yükleniyor'); const [notice, setNotice] = useState(null); const title = useMemo(() => navigation.find(([key]) => key === page)?.[1] || 'Panel', [page]);
  async function reload() { try { const [health, dashboard, productList, referenceData, locationList, movementList] = await Promise.all([request('/health'), request('/dashboard'), request('/products'), request('/reference-data'), request('/locations'), request('/movements')]); setApiStatus(health.database === 'connected' ? 'Bağlı' : 'Veritabanı bekleniyor'); setSummary(dashboard); setProducts(productList); setReferences(referenceData); setLocations(locationList); setMovements(movementList); } catch { setApiStatus('Veritabanı bağlantısı bekleniyor'); } }
  useEffect(() => { reload(); }, []);
  useEffect(() => { if (user) reload(); }, [user]);
  if (!authReady) return <div className="auth-loading">Oturum kontrol ediliyor…</div>;
  if (!user) return <LoginPage onAuthenticated={setUser} />;
  function logout() { request('/auth/logout', { method: 'POST' }).catch(() => {}).finally(() => { localStorage.removeItem('barfas_auth_token'); setUser(null); }); }
  function navigate(nextPage) { setPage(nextPage); setMenuOpen(false); setNotice(null); window.scrollTo({ top: 0, behavior: 'smooth' }); }
  return <div className="app-shell"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menüyü aç"><Menu size={22} /></button><div className="brand"><span className="brand-mark">B</span><span>Barfas <em>Depo</em></span></div><div className="breadcrumb-line"><span>DEPO YÖNETİMİ</span><strong>{title}</strong></div><div className="connection"><i className={apiStatus === 'Bağlı' ? 'online' : ''} />{apiStatus}</div></header><aside className={`sidebar ${menuOpen ? 'sidebar-open' : ''}`}><p className="nav-heading">OPERASYON</p>{navigation.map(([key, label, Icon]) => <button key={key} className={page === key ? 'nav-item active' : 'nav-item'} onClick={() => navigate(key)}><Icon size={19} />{label}</button>)}<div className="sidebar-help"><MapPin size={18} /><span>Her hareket, neden ve konumuyla kaydedilir.</span></div></aside><main className="content"><div className="page-heading"><div><p className="eyebrow">DEPO YÖNETİMİ</p><h1>{title}</h1></div></div><Notice notice={notice} />{page === 'panel' && <DashboardOverview summary={summary} movements={movements} navigate={navigate} />}{page === 'urunler' && <ProductPage products={products} references={references} reload={reload} setNotice={setNotice} navigate={navigate} />}{page === 'etiket' && <LabelPage references={references} reload={reload} setNotice={setNotice} />}{page === 'konumlar' && <LocationPage locations={locations} reload={reload} setNotice={setNotice} />}{page === 'yonetim' && <ManagementPage references={references} reload={reload} setNotice={setNotice} />}{page === 'giris' && <MovementPage type="IN" references={references} reload={reload} setNotice={setNotice} />}{page === 'cikis' && <MovementPage type="OUT" references={references} reload={reload} setNotice={setNotice} />}{page === 'transfer' && <MovementPage type="TRANSFER" references={references} reload={reload} setNotice={setNotice} />}{page === 'iade' && <MovementPage type="RETURN" references={references} reload={reload} setNotice={setNotice} />}{page === 'sayim' && <MovementPage type="COUNT" references={references} reload={reload} setNotice={setNotice} />}</main></div>;
}

export default App;
